class Solution {
  public int longestBalanced(String s) {
    int best = 0;
    for (int i = 0; i < s.length(); i++) {
      int[] freq = new int[26];
      int distinct = 0, maxFreq = 0;
      for (int j = i; j < s.length(); j++) {
        int c = s.charAt(j) - 'a';
        if (freq[c]++ == 0) distinct++;
        maxFreq = Math.max(maxFreq, freq[c]);
        // every distinct letter has the same count iff the length equals distinct * maxFreq
        if (distinct * maxFreq == j - i + 1) best = Math.max(best, j - i + 1);
      }
    }
    return best;
  }
}
